const md5 = (input) => {
  function add(x,y){const l=(x&65535)+(y&65535);return(((x>>>16)+(y>>>16)+(l>>>16))<<16)|(l&65535)}
  function rol(n,c){return(n<<c)|(n>>>(32-c))} function cm(q,a,b,x,s,t){return add(rol(add(add(a,q),add(x,t)),s),b)}
  function ff(a,b,c,d,x,s,t){return cm((b&c)|(~b&d),a,b,x,s,t)} function gg(a,b,c,d,x,s,t){return cm((b&d)|(c&~d),a,b,x,s,t)}
  function hh(a,b,c,d,x,s,t){return cm(b^c^d,a,b,x,s,t)} function ii(a,b,c,d,x,s,t){return cm(c^(b|~d),a,b,x,s,t)}
  const raw=unescape(encodeURIComponent(String(input))); const n=raw.length, words=[];
  for(let i=0;i<n;i++) words[i>>2]=(words[i>>2]||0)|(raw.charCodeAt(i)<<((i%4)*8));
  words[n>>2]=(words[n>>2]||0)|(0x80<<((n%4)*8)); words[(((n+8)>>6)<<4)+14]=n*8;
  let a=1732584193,b=-271733879,c=-1732584194,d=271733878;
  const S=[[7,12,17,22],[5,9,14,20],[4,11,16,23],[6,10,15,21]], K=[];
  for(let i=0;i<64;i++)K[i]=(Math.abs(Math.sin(i+1))*4294967296)|0;
  for(let i=0;i<words.length;i+=16){let A=a,B=b,C=c,D=d;
    for(let j=0;j<64;j++){let g,f;if(j<16){g=j;f=ff(a,b,c,d,words[i+g]||0,S[0][j%4],K[j])}else if(j<32){g=(5*j+1)%16;f=gg(a,b,c,d,words[i+g]||0,S[1][j%4],K[j])}else if(j<48){g=(3*j+5)%16;f=hh(a,b,c,d,words[i+g]||0,S[2][j%4],K[j])}else{g=(7*j)%16;f=ii(a,b,c,d,words[i+g]||0,S[3][j%4],K[j])}a=d;d=c;c=b;b=f} a=add(a,A);b=add(b,B);c=add(c,C);d=add(d,D)}
  return [a,b,c,d].map(v=>[0,8,16,24].map(s=>(v>>>s&255).toString(16).padStart(2,"0")).join("")).join("");
};
function acgScalar(value){if(value===true)return"1";if(value===false)return"0";return String(value)}
function appendAcgPairs(pairs,key,value){
  if(value===null||value===undefined)return;
  if(Array.isArray(value)){value.forEach((item,index)=>appendAcgPairs(pairs,`${key}[${index}]`,item));return}
  if(typeof value==="object"){for(const [child,item] of Object.entries(value))appendAcgPairs(pairs,`${key}[${child}]`,item);return}
  pairs.push([key,acgScalar(value)]);
}
function acgFormPairs(data){
  const pairs=[];
  for(const key of Object.keys(data).filter(key=>key!=="sign"&&data[key]!=="").sort())appendAcgPairs(pairs,key,data[key]);
  return pairs;
}
const acgSign=(data,key)=>md5(acgFormPairs(data).map(([name,value])=>`${name}=${value}`).join("&")+"&key="+key);
function acgFormBody(data){const form=new URLSearchParams();for(const [name,value] of acgFormPairs(data))form.append(name,value);if(data.sign!==undefined)form.append("sign",String(data.sign));return form}
function parseAcgForm(raw){
  const result={},blocked=new Set(["__proto__","prototype","constructor"]);let fields=0;
  for(const [name,value] of new URLSearchParams(raw)){
    if(++fields>1000||name.length>160)throw new Error("FORM_TOO_COMPLEX");
    const base=name.match(/^[^[]+/)?.[0];if(!base)continue;
    const parts=[base,...[...name.matchAll(/\[([^\]]*)\]/g)].map(match=>match[1])];
    if(parts.length>8||parts.some(part=>blocked.has(part)))throw new Error("INVALID_FORM_FIELD");
    let target=result;
    for(let index=0;index<parts.length-1;index++){
      const part=parts[index],next=parts[index+1],container=next===""||/^\d+$/.test(next)?[]:{};
      if(target[part]===undefined||target[part]===null||typeof target[part]!=="object")target[part]=container;
      target=target[part];
    }
    let leaf=parts.at(-1);if(leaf===""&&Array.isArray(target))leaf=String(target.length);target[leaf]=value;
  }
  return result;
}

async function aesKey(env) {
  if (!env.MASTER_KEY || env.MASTER_KEY.length < 32) throw new Error("MASTER_KEY_MISSING");
  return crypto.subtle.importKey("raw", new Uint8Array(await crypto.subtle.digest("SHA-256", bytes(env.MASTER_KEY))), "AES-GCM", false, ["encrypt", "decrypt"]);
}
async function seal(env, value) { const iv=crypto.getRandomValues(new Uint8Array(12)); const out=await crypto.subtle.encrypt({name:"AES-GCM",iv},await aesKey(env),bytes(value)); return `v1.${b64(iv)}.${b64(new Uint8Array(out))}`; }
async function openSeal(env, value) { if(!value)return ""; const [,iv,data]=value.split("."); return dec.decode(await crypto.subtle.decrypt({name:"AES-GCM",iv:unb64(iv)},await aesKey(env),unb64(data))); }
let schemaBinding=null,schemaPromise=null,legacyBinding=null,legacyPromise=null;
const settingsCache=new WeakMap(),SETTINGS_CACHE_TTL=30000,SECRET_CACHE_TTL=5000,localRateWindows=new Map();
async function runSchemaStatements(env,statements){
  if(!statements.length)return;
  if(typeof env.DB.exec==="function"){await env.DB.exec(statements.join(";\n"));return}
  for(const sql of statements)await env.DB.prepare(sql).run();
}
async function ensureSchema(env){
  if(!env.DB)throw new Error("DB_BINDING_MISSING");
  if(schemaBinding===env.DB&&schemaPromise)return schemaPromise;
  schemaBinding=env.DB;
  schemaPromise=(async()=>{
    let bootstrap=false,upgraded=false;
    try{await Promise.all([env.DB.prepare("SELECT 1 AS ok FROM upstream_connections LIMIT 1").all(),env.DB.prepare("SELECT 1 AS ok FROM job_locks LIMIT 1").all(),env.DB.prepare("SELECT 1 AS ok FROM next_catalog_products LIMIT 1").all()])}
    catch{await runSchemaStatements(env,SCHEMA.filter(sql=>!/^CREATE (?:UNIQUE )?INDEX/i.test(sql)));bootstrap=true}
    try{await env.DB.prepare("SELECT published,available FROM product_mappings LIMIT 1").all()}
    catch{for(const sql of ["ALTER TABLE product_mappings ADD COLUMN published INTEGER NOT NULL DEFAULT 1","ALTER TABLE product_mappings ADD COLUMN available INTEGER NOT NULL DEFAULT 1"])try{await env.DB.prepare(sql).run();upgraded=true}catch(e){if(!/duplicate column/i.test(String(e.message||e)))throw e}}
    const orderSchema=await env.DB.prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name='bridge_orders'").first();
    if(/CHECK\s*\(\s*direction/i.test(String(orderSchema?.sql||""))){
      const create="CREATE TABLE bridge_orders_v6 (id TEXT PRIMARY KEY,direction TEXT NOT NULL,downstream_order_no TEXT NOT NULL,upstream_order_id TEXT NOT NULL DEFAULT '',upstream_order_no TEXT NOT NULL DEFAULT '',public_product_id TEXT NOT NULL DEFAULT '',public_sku_id TEXT NOT NULL DEFAULT '',quantity INTEGER NOT NULL DEFAULT 1,amount TEXT NOT NULL DEFAULT '0.00',currency TEXT NOT NULL DEFAULT 'CNY',status TEXT NOT NULL DEFAULT 'creating',delivery_cipher TEXT NOT NULL DEFAULT '',delivery_hash TEXT NOT NULL DEFAULT '',initial_delivery_hash TEXT NOT NULL DEFAULT '',callback_url_cipher TEXT NOT NULL DEFAULT '',callback_state TEXT NOT NULL DEFAULT 'pending',callback_attempts INTEGER NOT NULL DEFAULT 0,last_error_code TEXT NOT NULL DEFAULT '',next_poll_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,delivered_at TEXT,UNIQUE(direction,downstream_order_no))",columns="id,direction,downstream_order_no,upstream_order_id,upstream_order_no,public_product_id,public_sku_id,quantity,amount,currency,status,delivery_cipher,delivery_hash,initial_delivery_hash,callback_url_cipher,callback_state,callback_attempts,last_error_code,next_poll_at,created_at,updated_at,delivered_at";
      await runSchemaStatements(env,["DROP TABLE IF EXISTS bridge_orders_v6",create,`INSERT INTO bridge_orders_v6(${columns}) SELECT ${columns} FROM bridge_orders`,"DROP TABLE bridge_orders","ALTER TABLE bridge_orders_v6 RENAME TO bridge_orders"]);upgraded=true;
    }
    const selectionIndex=await env.DB.prepare("SELECT name FROM sqlite_master WHERE type='index' AND name='product_mappings_selection_idx'").first();
    if(bootstrap||upgraded||!selectionIndex)await runSchemaStatements(env,SCHEMA.filter(sql=>/^CREATE (?:UNIQUE )?INDEX/i.test(sql)));
  })().catch(e=>{schemaBinding=null;schemaPromise=null;throw e});
  return schemaPromise;
}
function settingCache(env){let cache=settingsCache.get(env.DB);if(!cache){cache=new Map();settingsCache.set(env.DB,cache)}return cache;}
async function getSettings(env,keys){const cache=settingCache(env),stamp=Date.now(),result={},missing=[];for(const key of keys){const hit=cache.get(key);if(hit&&hit.expires>stamp)result[key]=hit.value;else missing.push(key)}if(missing.length){const marks=missing.map(()=>"?").join(","),rows=(await env.DB.prepare(`SELECT key,value,secret FROM settings WHERE key IN (${marks})`).bind(...missing).all()).results||[],byKey=new Map(rows.map(row=>[row.key,row]));for(const key of missing){const row=byKey.get(key),value=row?(row.secret?await openSeal(env,row.value):row.value):"",ttl=SECRET_KEYS.has(key)?SECRET_CACHE_TTL:SETTINGS_CACHE_TTL;cache.set(key,{value,expires:stamp+ttl});result[key]=value}}return result;}
async function getSetting(env,key){return (await getSettings(env,[key]))[key]||"";}
async function setSetting(env,key,value,secret=SECRET_KEYS.has(key)){const plain=String(value);if(await getSetting(env,key)===plain)return false;const stored=secret?await seal(env,plain):plain;await env.DB.prepare("INSERT INTO settings(key,value,secret,updated_at) VALUES(?,?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,secret=excluded.secret,updated_at=excluded.updated_at").bind(key,stored,secret?1:0,now()).run();settingCache(env).set(key,{value:plain,expires:Date.now()+(secret?SECRET_CACHE_TTL:SETTINGS_CACHE_TTL)});return true;}
async function runBatches(env,statements,size=80){for(let i=0;i<statements.length;i+=size)await env.DB.batch(statements.slice(i,i+size));}
async function listConnections(env,platform="",activeOnly=false){let sql="SELECT * FROM upstream_connections",args=[];const where=[];if(platform){where.push("platform=?");args.push(platform)}if(activeOnly)where.push("active=1");if(where.length)sql+=` WHERE ${where.join(" AND ")}`;sql+=" ORDER BY priority,id";return (await env.DB.prepare(sql).bind(...args).all()).results;}
async function getConnection(env,value,platform=""){const key=Number(value||0);if(key){const row=await env.DB.prepare("SELECT * FROM upstream_connections WHERE id=?").bind(key).first();if(row&&(!platform||row.platform===platform))return row;}return (await listConnections(env,platform,true))[0]||null;}
async function connectionSecrets(env,row){if(!row)return {id:"",secret:""};return {id:row.api_id_cipher?await openSeal(env,row.api_id_cipher):"",secret:row.api_secret_cipher?await openSeal(env,row.api_secret_cipher):""};}
async function migrateLegacyConnections(env){
  if(typeof env.DB.prepare("SELECT 1").bind!=="function")return;
  if(await getSetting(env,"connections_migrated_v2")){await adoptLegacyMappings(env);return;}
  const count=Number((await env.DB.prepare("SELECT COUNT(*) AS n FROM upstream_connections").first())?.n||0);let created=0;
  if(!count){for(const platform of ["acg","next"]){const url=await getSetting(env,`${platform}_upstream_url`);if(!url)continue;const idValue=await getSetting(env,platform==="acg"?"acg_upstream_app_id":"next_upstream_api_key"),secretValue=await getSetting(env,platform==="acg"?"acg_upstream_app_key":"next_upstream_api_secret");await env.DB.prepare("INSERT INTO upstream_connections(name,platform,base_url,api_id_cipher,api_secret_cipher,catalog_mode,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)").bind(platform==="acg"?"异次元上游":"Dujiao-Next 上游",platform,externalUrl(url).origin+(externalUrl(url).pathname==="/"?"":externalUrl(url).pathname),idValue?await seal(env,idValue):"",secretValue?await seal(env,secretValue):"",platform==="acg"?(await getSetting(env,"acg_catalog_mode")||"auto"):"auto",now(),now()).run();created++}}
  if(count||created){await setSetting(env,"connections_migrated_v2","1",false);await adoptLegacyMappings(env);}
}
async function ensureLegacyConnections(env){if(legacyBinding===env.DB&&legacyPromise)return legacyPromise;legacyBinding=env.DB;legacyPromise=migrateLegacyConnections(env).catch(e=>{legacyBinding=null;legacyPromise=null;throw e});return legacyPromise;}
const PRICING_MODES=new Set(["inherit","none","percent","fixed","set"]);
function priceNumber(value,fallback=0){const n=Number(value);return Number.isFinite(n)&&n>=0?n:fallback;}
function applyPricing(cost,mode,value,minPrice=0){const base=priceNumber(cost),v=priceNumber(value),floor=priceNumber(minPrice);let result=base;if(mode==="percent")result=base*(1+v/100);else if(mode==="fixed")result=base+v;else if(mode==="set")result=v;return Math.max(result,floor).toFixed(2);}
async function pricingContext(env,connection){let globalMode="none",globalValue="0",globalMin="0",rows=[];if(env.DB){const settings=await getSettings(env,["global_markup_mode","global_markup_value","global_min_price"]);globalMode=settings.global_markup_mode||"none";globalValue=settings.global_markup_value||"0";globalMin=settings.global_min_price||"0";rows=(await env.DB.prepare("SELECT product_key,mode,value,min_price FROM price_rules WHERE connection_id=? AND active=1").bind(connection.id).all()).results}return {connection,globalMode,globalValue,globalMin,rules:new Map(rows.map(row=>[String(row.product_key),row]))};}
function priceFromContext(context,productKey,cost){const connection=context.connection,rule=context.rules.get(String(productKey));let mode=rule?.mode||connection.markup_mode||"inherit",value=rule?.value??connection.markup_value,minPrice=rule?.min_price??connection.min_price,scope=rule?"product":"upstream";if(mode==="inherit"){mode=context.globalMode||"none";value=context.globalValue||"0";minPrice=context.globalMin||"0";scope="global"}if(!PRICING_MODES.has(mode)||mode==="inherit")mode="none";return {price:applyPricing(cost,mode,value,minPrice),mode,value:String(value||0),min_price:String(minPrice||0),scope};}
async function resolvePrice(env,connection,productKey,cost){return priceFromContext(await pricingContext(env,connection),productKey,cost);}
async function fetchWithTimeout(url,options={},timeoutMs=12000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);try{return await fetch(url,{...options,signal:controller.signal})}catch(e){if(e?.name==="AbortError")throw new Error("UPSTREAM_TIMEOUT");throw e}finally{clearTimeout(timer)}}
async function notifyTelegram(env,type,text){try{if((await getSetting(env,"telegram_enabled"))!=="1")return;if((await getSetting(env,`telegram_${type}_notifications`))==="0")return;const token=await getSetting(env,"telegram_bot_token"),chatId=await getSetting(env,"telegram_chat_id");if(!token||!chatId)return;const safe=String(text).replace(/https?:\/\/\S+/g,"[已隐藏地址]").slice(0,3500);const res=await fetch(`https://api.telegram.org/bot${token}/sendMessage`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({chat_id:chatId,text:`Faka Bridge\n${safe}`,disable_web_page_preview:true}),redirect:"manual"});if(!res.ok)throw new Error(`TELEGRAM_HTTP_${res.status}`)}catch(e){console.error("telegram_error",cleanText(e.message,48));}}
async function updateHealth(env,connection,ok,error="",responseMs=0){const was=connection.health_status||"unknown",fail=ok?0:Math.min(3,Number(connection.consecutive_failures||0)+1),success=ok?Math.min(2,Number(connection.consecutive_successes||0)+1):0,next=ok?(was==="down"&&success<2?"down":"healthy"):(fail>=3?"down":was),errorCode=ok?"":cleanText(error,48),lastCheck=Date.parse(connection.last_checked_at||""),heartbeatDue=!Number.isFinite(lastCheck)||Date.now()-lastCheck>=30*60*1000,stateChanged=next!==was||fail!==Number(connection.consecutive_failures||0)||success!==Number(connection.consecutive_successes||0)||errorCode!==String(connection.last_error_code||"");if(stateChanged||heartbeatDue){const stamp=now();await env.DB.prepare("UPDATE upstream_connections SET health_status=?,consecutive_failures=?,consecutive_successes=?,last_checked_at=?,last_ok_at=CASE WHEN ?=1 THEN ? ELSE last_ok_at END,last_error_code=?,response_ms=?,updated_at=? WHERE id=?").bind(next,fail,success,stamp,ok?1:0,stamp,errorCode,Math.max(0,Math.round(responseMs)),stamp,connection.id).run()}if(next!==was&&next==="down")await notifyTelegram(env,"health",`上游异常：${cleanText(connection.name,60)}\n连续失败 ${fail} 次\n错误代码：${cleanText(error,48)}`);if(was==="down"&&next==="healthy")await notifyTelegram(env,"health",`上游恢复：${cleanText(connection.name,60)}\n连续 ${success} 次检测正常`);return {written:stateChanged||heartbeatDue,next,fail,success};}
const securityHeaders = {"x-content-type-options":"nosniff","x-frame-options":"DENY","referrer-policy":"no-referrer","permissions-policy":"camera=(), microphone=(), geolocation=()","content-security-policy":"default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'"};
