function externalUrl(value,allowPath=true){const u=new URL(value),h=u.hostname.toLowerCase().replace(/^\[|\]$/g,"");if(u.protocol!=="https:")throw new Error("HTTPS_REQUIRED");if(u.username||u.password)throw new Error("URL_CREDENTIALS_DENIED");if(u.port&&u.port!=="443")throw new Error("HTTPS_PORT_REQUIRED");if(!allowPath&&(u.pathname!=="/"||u.search||u.hash))throw new Error("HOST_ONLY");const v4=h.match(/^(\d+)\.(\d+)\.(\d+)\.(\d+)$/)?.slice(1).map(Number),isV6=h.includes(":");const privateV4=v4&&(v4.some(n=>n<0||n>255)||v4[0]===10||v4[0]===127||v4[0]===0||v4[0]===169&&v4[1]===254||v4[0]===192&&v4[1]===168||v4[0]===172&&v4[1]>=16&&v4[1]<=31||v4[0]>=224);if(privateV4||isV6||h==="localhost"||h.endsWith(".local")||h.endsWith(".internal")||!h.includes("."))throw new Error("PRIVATE_HOST");return u;}
