async function enforceApiRate(req,env,scope,limit=120,windowSeconds=60){const actor=req.headers.get("dujiao-next-api-key")||req.headers.get("cf-connecting-ip")||"unknown",key=await hmac(env.MASTER_KEY||env.SESSION_SECRET||"faka-bridge",`${scope}:${actor}`);if(env.API_RATE_LIMITER?.limit){try{return !!(await env.API_RATE_LIMITER.limit({key})).success}catch{}}const ts=Math.floor(Date.now()/1000),row=localRateWindows.get(key);if(!row||ts-row.started>=windowSeconds){localRateWindows.set(key,{started:ts,count:1});return true}row.count++;if(localRateWindows.size>2000)for(const [entry,value] of localRateWindows)if(ts-value.started>=windowSeconds)localRateWindows.delete(entry);return row.count<=limit;}
