async function sessionToken(env,payload){const p=b64(bytes(JSON.stringify(payload))).replaceAll("=","");return `${p}.${await hmac(env.SESSION_SECRET,p)}`;}
async function parseSession(req,env){const raw=(req.headers.get("cookie")||"").split(";").map(x=>x.trim()).find(x=>x.startsWith("fb_session="))?.slice(11);if(!raw||!env.SESSION_SECRET)return null;const dot=raw.lastIndexOf(".");if(dot<0)return null;const p=raw.slice(0,dot),sig=raw.slice(dot+1);if(!safeEqual(sig,await hmac(env.SESSION_SECRET,p)))return null;try{const obj=JSON.parse(dec.decode(unb64(p)));return obj.exp>Date.now()?obj:null}catch{return null}}
async function requireAdmin(req,env,mutating=false){const s=await parseSession(req,env);if(!s)return null;if(mutating){const origin=req.headers.get("origin"),expected=new URL(req.url).origin;if(origin!==expected||!safeEqual(req.headers.get("x-csrf-token")||"",s.csrf))return null;}return s;}
async function login(req,env){if(!env.ADMIN_PASSWORD||env.ADMIN_PASSWORD.length<12||!env.SESSION_SECRET||env.SESSION_SECRET.length<32)return genericError("SERVER_NOT_CONFIGURED",503);const ip=req.headers.get("cf-connecting-ip")||"unknown",subject=await hmac(env.SESSION_SECRET,ip),ts=Math.floor(Date.now()/1000);const row=await env.DB.prepare("SELECT * FROM admin_login_attempts WHERE subject_hash=?").bind(subject).first();if(row&&row.blocked_until>ts)return genericError("TOO_MANY_ATTEMPTS",429);const {data}=await readJson(req,4096),username=String(env.ADMIN_USERNAME||"admin"),valid=safeEqual(String(data.username||""),username)&&safeEqual(String(data.password||""),env.ADMIN_PASSWORD);if(!valid){const fresh=!row||ts-row.window_started_at>900, attempts=fresh?1:row.attempts+1,blocked=attempts>=5?ts+900:0;await env.DB.prepare("INSERT INTO admin_login_attempts(subject_hash,attempts,window_started_at,blocked_until) VALUES(?,?,?,?) ON CONFLICT(subject_hash) DO UPDATE SET attempts=excluded.attempts,window_started_at=excluded.window_started_at,blocked_until=excluded.blocked_until").bind(subject,attempts,fresh?ts:row.window_started_at,blocked).run();return genericError("LOGIN_FAILED",401)}await env.DB.prepare("DELETE FROM admin_login_attempts WHERE subject_hash=?").bind(subject).run();const csrf=crypto.randomUUID(),token=await sessionToken(env,{exp:Date.now()+8*3600e3,csrf,username});return new Response(JSON.stringify({ok:true,csrf}),{headers:{...securityHeaders,...JSON_HEADERS,"cache-control":"no-store","set-cookie":`fb_session=${token}; Path=/; Max-Age=28800; HttpOnly; Secure; SameSite=Strict`}});}

async function nextFetchConnection(env,connection,path,method="GET",body=null){if(!connection)throw new Error("NEXT_NOT_CONFIGURED");const base=externalUrl(connection.base_url),target=new URL(path,base),credentials=await connectionSecrets(env,connection),key=credentials.id,secret=credentials.secret;if(!key||!secret)throw new Error("NEXT_NOT_CONFIGURED");const raw=body?JSON.stringify(body):"",verb=method.toUpperCase(),ts=Math.floor(Date.now()/1000).toString(),sig=await hmac(secret,`${verb}\n${target.pathname}\n${ts}\n${md5(raw)}`);const res=await fetchWithTimeout(target,{method:verb,headers:{"content-type":"application/json","Dujiao-Next-Api-Key":key,"Dujiao-Next-Timestamp":ts,"Dujiao-Next-Signature":sig},body:body?raw:null,redirect:"manual"}),text=await res.text();let out={};try{out=text?JSON.parse(text):{}}catch{}const safeCode=cleanText(out?.error_code||`HTTP_${res.status}`,40).toUpperCase();if(!res.ok)throw new Error(`NEXT_${safeCode}`);if(out?.ok===false)throw new Error(`NEXT_${safeCode||"REJECTED"}`);return out;}
async function acgFetchConnection(env,connection,path,data={}){if(!connection)throw new Error("ACG_NOT_CONFIGURED");const base=externalUrl(connection.base_url),credentials=await connectionSecrets(env,connection),app_id=credentials.id,app_key=credentials.secret;if(!app_id||!app_key)throw new Error("ACG_NOT_CONFIGURED");const body={...data,app_id};body.sign=acgSign(body,app_key);const res=await fetchWithTimeout(new URL(path,base),{method:"POST",headers:{"content-type":"application/x-www-form-urlencoded"},body:acgFormBody(body),redirect:"manual"});if(!res.ok)throw new Error(`ACG_HTTP_${res.status}`);const out=await res.json();if(Number(out.code)!==200)throw new Error(`ACG_UPSTREAM_REJECTED_${cleanText(out.msg||"UNKNOWN",48)}`);return out.data??out;}
